using System;
using System.Collections.Generic;
using System.Threading.Tasks;

public record DomainEvent(Guid EventId, string AccountNumber, decimal Amount);

public class IdempotentEventConsumer
{
    private readonly HashSet<Guid> _processedEventStore = new();
    private decimal _totalBalance = 0;

    public Task ProcessEventAsync(DomainEvent ev)
    {
        if (_processedEventStore.Contains(ev.EventId))
        {
            Console.WriteLine($"[DUPLICATE] Event {ev.EventId} diabaikan.");
            return Task.CompletedTask;
        }

        _totalBalance += ev.Amount;
        _processedEventStore.Add(ev.EventId);
        Console.WriteLine($"[PROCESSED] Saldo baru: Rp {_totalBalance:N0}");

        return Task.CompletedTask;
    }

    public decimal GetBalance() => _totalBalance;
}

public class Program
{
    public static async Task Main()
    {
        var consumer = new IdempotentEventConsumer();
        var sharedEventId = Guid.NewGuid();

        var ev1 = new DomainEvent(sharedEventId, "ACC-001", 500_000);
        var evDuplicate = new DomainEvent(sharedEventId, "ACC-001", 500_000);
        var ev3 = new DomainEvent(Guid.NewGuid(), "ACC-001", 200_000);

        await consumer.ProcessEventAsync(ev1);
        await consumer.ProcessEventAsync(evDuplicate);
        await consumer.ProcessEventAsync(ev3);

        Console.WriteLine($"\nSaldo Akhir yang Benar: Rp {consumer.GetBalance():N0} (Ekspektasi: Rp 700.000)");
    }
}
